mapper.select:

WHERE k.wms_tenant_id=#{wmsTenantId}
AND k.erp_tenant_id=#{qo.erpTenantId}
AND k.currency=UPPER(#{qo.currency})
AND (COALESCE(r.recharge_amount,0)-COALESCE(c.charge_amount,0) < 0)=#{qo.negative}
ORDER BY et.tenant_name, k.currency

 WHERE 1=1
AND k.wms_tenant_id=#{qo.wmsTenantId}
AND k.currency=UPPER(#{qo.currency})
AND (COALESCE(r.recharge_amount,0)-COALESCE(c.charge_amount,0) < 0)=#{qo.negative}
ORDER BY wt.tenant_name, k.currency

SELECT r.*, wt.tenant_name wmsTenantName, et.tenant_name erpTenantName
  FROM wms_recharge_order r
  LEFT JOIN sys_tenant wt ON wt.id=r.wms_tenant_id
  LEFT JOIN sys_tenant et ON et.id=r.erp_tenant_id
 WHERE r.account_scope=#{scope}
AND r.wms_tenant_id=#{wmsTenantId}
AND r.erp_tenant_id=#{erpTenantId}
AND r.status=#{qo.status}
AND UPPER(r.currency)=UPPER(#{qo.currency})
AND r.create_time >= #{qo.startDate}
AND r.create_time < DATE_ADD(#{qo.endDate}, INTERVAL 1 DAY)
ORDER BY r.id DESC
